154	    if tag::is_raw(element.tag) {
155	        write_raw(w, element)?;
156	    } else if tag::is_escapable_raw(element.tag) {
157	        write_escapable_raw(w, element)?;
158	    } else if !element.children.is_empty() {
159	        write_children(w, element)?;
160	    }
