273	    mut f: impl FnMut(&str, Span) -> SourceResult<()>,
274	) -> SourceResult<()> {
275	    for c in &element.children {
276	        match c {
277	            HtmlNode::Tag(_) => {}
278	            HtmlNode::Text(text, span) => f(text, *span)?,
279	            HtmlNode::Element(HtmlElement { span, .. })
280	            | HtmlNode::Frame(HtmlFrame { span, .. }) => {
