37	/// Execute a compilation command.
38	pub fn compile(command: &'static CompileCommand) -> HintedStrResult<()> {
39	    let mut timer = Timer::new_or_placeholder(command.args.timings.clone());
40	    let mut config = CompileConfig::new(command)?;
41	    let mut world = SystemWorld::new(
42	        Some(&command.args.input),
43	        &command.args.world,
44	        &command.args.process,
45	    )
46	    .map_err(|err| eco_format!("{err}"))?;
47	    timer.record(&mut world, |world| compile_once(world, &mut config))?
48	}
