440	/// Convert [`chrono::DateTime`] to [`Datetime`]
441	fn convert_datetime<Tz: chrono::TimeZone>(
442	    date_time: chrono::DateTime<Tz>,
443	) -> Option<Datetime> {
444	    Datetime::from_ymd_hms(
445	        date_time.year(),
446	        date_time.month().try_into().ok()?,
447	        date_time.day().try_into().ok()?,
448	        date_time.hour().try_into().ok()?,
449	        date_time.minute().try_into().ok()?,
450	        date_time.second().try_into().ok()?,
451	    )
452	}
