461	/// Export to one or multiple images.
462	fn export_image(
463	    document: &PagedDocument,
464	    config: &CompileConfig,
465	    fmt: ImageExportFormat,
466	) -> StrResult<Vec<Output>> {
467	    // Determine whether we have indexable templates in output
468	    let can_handle_multiple = match config.output {
469	        Output::Stdout => false,
470	        Output::Path(ref output) => {
471	            output_template::has_indexable_template(output.to_str().unwrap_or_default())
472	        }
473	    };
474	
475	    let exported_pages = document
476	        .pages()
477	        .iter()
478	        .enumerate()
479	        .filter(|(i, _)| {
480	            config.pages.as_ref().is_none_or(|exported_page_ranges| {
481	                exported_page_ranges.includes_page_index(*i)
482	            })
483	        })
484	        .collect::<Vec<_>>();
485	
486	    if !can_handle_multiple && exported_pages.len() > 1 {
487	        let err = match config.output {
488	            Output::Stdout => "to stdout",
489	            Output::Path(_) => {
490	                "without a page number template ({p}, {0p}) in the output path"
491	            }
492	        };
493	        bail!("cannot export multiple images {err}");
494	    }
495	
496	    // The results are collected in a `Vec<()>` which does not allocate.
497	    exported_pages
498	        .par_iter()
499	        .map(|(i, page)| {
500	            // Use output with converted path.
501	            let output = match &config.output {
502	                Output::Path(path) => {
503	                    let storage;
504	                    let path = if can_handle_multiple {
505	                        storage = output_template::format(
506	                            path.to_str().unwrap_or_default(),
507	                            i + 1,
508	                            document.pages().len(),
509	                        );
510	                        Path::new(&storage)
511	                    } else {
512	                        path
513	                    };
514	
515	                    // If we are not watching, don't use the cache.
516	                    // If the frame is in the cache, skip it.
517	                    // If the file does not exist, always create it.
518	                    if config.watching
519	                        && config.export_cache.is_cached(*i, page)
520	                        && path.exists()
521	                    {
522	                        return Ok(Output::Path(path.to_path_buf()));
523	                    }
524	
525	                    Output::Path(path.to_owned())
526	                }
527	                Output::Stdout => Output::Stdout,
528	            };
529	
530	            export_image_page(config, page, &output, fmt)?;
531	            Ok(output)
532	        })
533	        .collect::<StrResult<Vec<Output>>>()
534	}
535	
536	mod output_template {
537	    const INDEXABLE: [&str; 3] = ["{p}", "{0p}", "{n}"];
538	
539	    pub fn has_indexable_template(output: &str) -> bool {
540	        INDEXABLE.iter().any(|template| output.contains(template))
541	    }
542	
543	    pub fn format(output: &str, this_page: usize, total_pages: usize) -> String {
544	        // Find the base 10 width of number `i`
545	        fn width(i: usize) -> usize {
546	            1 + i.checked_ilog10().unwrap_or(0) as usize
547	        }
548	
549	        let other_templates = ["{t}"];
550	        INDEXABLE.iter().chain(other_templates.iter()).fold(
551	            output.to_string(),
552	            |out, template| {
553	                let replacement = match *template {
554	                    "{p}" => format!("{this_page}"),
555	                    "{0p}" | "{n}" => format!("{:01$}", this_page, width(total_pages)),
556	                    "{t}" => format!("{total_pages}"),
557	                    _ => unreachable!("unhandled template placeholder {template}"),
558	                };
559	                out.replace(template, replacement.as_str())
560	            },
561	        )
562	    }
563	}
