565	/// Export single image.
566	fn export_image_page(
567	    config: &CompileConfig,
568	    page: &Page,
569	    output: &Output,
570	    fmt: ImageExportFormat,
571	) -> StrResult<()> {
572	    match fmt {
573	        ImageExportFormat::Png => {
574	            let options = png_options(config);
575	            let pixmap = typst_render::render(page, &options);
576	            let buf = pixmap
577	                .encode_png()
578	                .map_err(|err| eco_format!("failed to encode PNG file ({err})"))?;
579	            output
580	                .write(&buf)
581	                .map_err(|err| eco_format!("failed to write PNG file ({err})"))?;
582	        }
583	        ImageExportFormat::Svg => {
584	            let options = svg_options(config);
585	            let svg = typst_svg::svg(page, &options);
586	            output
587	                .write(svg.as_bytes())
588	                .map_err(|err| eco_format!("failed to write SVG file ({err})"))?;
589	        }
590	    }
591	    Ok(())
592	}
