640	/// Caches exported files so that we can avoid re-exporting them if they haven't
641	/// changed.
642	///
643	/// This is done by having a list of size `files.len()` that contains the hashes
644	/// of the last rendered frame in each file. If a new frame is inserted, this
645	/// will invalidate the rest of the cache, this is deliberate as to decrease the
646	/// complexity and memory usage of such a cache.
647	pub struct ExportCache {
648	    /// The hashes of last compilation's frames.
649	    pub cache: RwLock<Vec<u128>>,
650	}
651	
652	impl ExportCache {
653	    /// Creates a new export cache.
654	    pub fn new() -> Self {
655	        Self { cache: RwLock::new(Vec::with_capacity(32)) }
656	    }
657	
658	    /// Returns true if the entry is cached and appends the new hash to the
659	    /// cache (for the next compilation).
660	    pub fn is_cached(&self, i: usize, page: &Page) -> bool {
661	        let hash = typst::utils::hash128(page);
662	
663	        let mut cache = self.cache.upgradable_read();
664	        if i >= cache.len() {
665	            cache.with_upgraded(|cache| cache.push(hash));
666	            return false;
667	        }
668	
669	        cache.with_upgraded(|cache| std::mem::replace(&mut cache[i], hash) == hash)
670	    }
671	}
